files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --btn: #0f3460;
  --btn-hover: #1a4a7a;
  --btn-press: #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', monospace;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  padding: 32px 24px;
  text-align: center;
  max-width: 400px;
  width: 100%;
  box-shadow: 8px 8px 0 var(--accent);
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 24px;
  color: var(--accent);
}

.count {
  font-size: 4rem;
  font-weight: bold;
  margin: 16px 0 32px;
  padding: 8px;
  background: var(--bg);
  border: 2px solid var(--accent);
  min-height: 1.5em;
  word-break: break-all;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1.25rem;
  padding: 12px 20px;
  background: var(--btn);
  color: var(--text);
  border: 3px solid var(--accent);
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
  min-width: 64px;
}

button:hover {
  background: var(--btn-hover);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  background: var(--btn-press);
  transform: translate(2px, 2px);
}

.hint {
  margin-top: 24px;
  font-size: 0.875rem;
  opacity: 0.7;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .count {
    font-size: 3rem;
  }
  button {
    font-size: 1rem;
    padding: 10px 14px;
  }
}

let count = 0;
const countEl = document.getElementById('count');

function updateDisplay() {
  countEl.textContent = count;
}

document.getElementById('increase').addEventListener('click', () => {
  count += 1;
  updateDisplay();
});

document.getElementById('decrease').addEventListener('click', () => {
  count -= 1;
  updateDisplay();
});

document.getElementById('reset').addEventListener('click', () => {
  count = 0;
  updateDisplay();
});

updateDisplay();
